    for(int i=0;i<2;i++) pthread_create(&t[i],NULL,worker,(void *)(intptr_t)i);
    for(int i=0;i<2;i++) pthread_join(t[i],NULL);
    pthread_barrier_destroy(&ready); puts("PASS"); return 0;
